fn get_min_val(a: &Vec<i8>) -> i8 {
    // Since array is non-empty, we can safely unwrap
    *a.iter().min().unwrap()
}

fn get_max_val(a: &Vec<i8>) -> i8 {
    // Since array is non-empty, we can safely unwrap
    *a.iter().max().unwrap()
}

fn nanquantile(a: Vec<i8>, q: i8) -> i8 {
    // Validate q is in [0, 100] (though problem says we can assume this)
    assert!(q >= 0 && q <= 100, "Quantile must be between 0 and 100");
    
    // Handle edge cases for q = 0 and q = 100
    if q == 0 {
        return get_min_val(&a);
    }
    if q == 100 {
        return get_max_val(&a);
    }
    
    // Sort the array to find quantile
    let mut sorted = a.clone();
    sorted.sort();
    
    // Calculate the index for the quantile
    // Using formula: index = round(q/100 * (n-1))
    let n = sorted.len();
    let index = ((q as f64 / 100.0) * (n - 1) as f64).round() as usize;
    
    // Return the element at the calculated index
    sorted[index]
}